('bildirimler', 'bil-th20260001', '{"tur": "tehlike", "no": "TH-2026-0001", "durum": "Yeni", "baslik": "İzoleli eldivenlerde aşırı aşınma", "tarih": "2026-09-24", "saat": "14:47", "saha": "Taşpınar Hybrid Santral", "konum": "Malzeme deposu", "aciklama": "Elektrik işlerinde kullanılan kauçuk izoleli eldivenlerde (GOTO marka, sınıf 00) yüzeyde yaygın çizik, sürtünme izi ve renk solması tespit edildi. Eldivenler kutu/malzeme deposunda diğer ekipmanlarla birlikte, koruyucu kılıf olmadan bulunuyor.", "siddet": "Yüksek", "anlikOnlem": "Eldivenler kullanım dışı bırakıldı.", "oneri": "Periyodik dielektrik testi (6 ayda bir) yaptırılsın, test tarihi etiketlensin; hasarlı/şüpheli eldivenler derhal imha edilip yenisiyle değiştirilsin; saklama için ayrı, güneş görmeyen kutu/çanta kullanılsın.", "anonim": false, "bildiren": "ozan.alemdar", "ekip": "İSG", "olusturan": "ozan.alemdar", "olusturma": "2026-09-24T14:47:24.000Z", "guncelleme": "2026-09-24T14:47:24.000Z", "guncelleyen": "ozan.alemdar"}', 0, 1790261244439, 'kurulum'),
('bildirimler', 'bil-th20260002', '{"tur": "tehlike", "no": "TH-2026-0002", "durum": "Yeni", "baslik": "Depoda dengesiz ve yüksek palet istifi", "tarih": "2026-09-24", "saat": "14:47", "saha": "Taşpınar Hybrid Santral", "konum": "Depo alanı", "aciklama": "Depo alanında çok sayıda ahşap kasa/palet, streç filmle sarılmış halde düzensiz ve dengesiz şekilde üst üste yığılmış. İstif, acil çıkış kapısına yakın konumda ve yürüme yolunu daraltıyor.", "siddet": "Yüksek", "anlikOnlem": "Alan çalışanlara sözlü olarak duyuruldu, yakınından geçiş sınırlandırıldı.", "oneri": "İstifler sökülüp raf sistemine ya da maksimum güvenli yüksekliğe göre yeniden düzenlensin; acil çıkış önü ve yürüme yolları sürekli açık tutulsun; düzenli depo/istif denetimi takvime bağlansın.", "anonim": false, "bildiren": "ozan.alemdar", "ekip": "İSG", "olusturan": "ozan.alemdar", "olusturma": "2026-09-24T14:47:24.000Z", "guncelleme": "2026-09-24T14:47:24.000Z", "guncelleyen": "ozan.alemdar"}', 0, 1790261244439, 'kurulum'),
('bildirimler', 'bil-th20260003', '{"tur": "tehlike", "no": "TH-2026-0003", "durum": "Yeni", "baslik": "LOTO etiketinde kimlik/tarih bilgisi boş", "tarih": "2026-09-24", "saat": "14:47", "saha": "Taşpınar Hybrid Santral", "konum": "Elektrik panosu", "aciklama": "Pano ayırıcısına turuncu kilit ve \"Tehlike – Çalıştırmayınız\" etiketi (LOCKSAN) takılmış, ancak etiket üzerindeki Ad, Bölümü ve Bitiş Tarihi alanları doldurulmamış.", "siddet": "Orta", "anlikOnlem": "", "oneri": "LOTO etiketleri takılırken ad, bölüm ve bitiş tarihi anında doldurulsun; kilidi takan kişi dışında kimse kilidi/etiketi kaldıramaz kuralı hatırlatılsın; LOTO prosedürü ekiplere tekrar duyurulsun.", "anonim": false, "bildiren": "ozan.alemdar", "ekip": "İSG", "olusturan": "ozan.alemdar", "olusturma": "2026-09-24T14:47:24.000Z", "guncelleme": "2026-09-24T14:47:24.000Z", "guncelleyen": "ozan.alemdar"}', 0, 1790261244439, 'kurulum')
